package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_sqrt_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testSqrt_NaN() {
        Complex c = new Complex(Double.NaN, 0.0);
        Complex result = c.sqrt();
        assertEquals(Complex.NaN, result);
    }

    @Test
    public void testSqrt_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.sqrt();
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testSqrt_PositiveReal() {
        // sqrt(4 + 0i) = 2 + 0i
        Complex c = new Complex(4.0, 0.0);
        Complex result = c.sqrt();
        assertEquals(2.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testSqrt_PositiveRealWithImaginary() {
        // sqrt(3 + 4i)
        // abs = 5. t = sqrt((3+5)/2) = 2.
        // real >= 0: real = 2, imag = 4 / (2*2) = 1
        Complex c = new Complex(3.0, 4.0);
        Complex result = c.sqrt();
        assertEquals(2.0, result.getReal(), EPSILON);
        assertEquals(1.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testSqrt_NegativeReal() {
        // sqrt(-4 + 0i)
        // abs = 4. t = sqrt((4+4)/2) = 2.
        // real < 0: real = |0| / (2*2) = 0, imag = indicator(0)*2 = 2 (Note: MathUtils.indicator(0) usually returns 1 or 0, 
        // but standard complex sqrt of -4 is 2i)
        // Based on logic: real = abs(0)/(2*2) = 0. imag = indicator(0)*2.
        // If indicator(0) is 1: result is 0 + 2i.
        Complex c = new Complex(-4.0, 0.0);
        Complex result = c.sqrt();
        // Since indicator(0.0) behavior depends on MathUtils implementation, 
        // we check for the mathematical expectation.
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(2.0, Math.abs(result.getImaginary()), EPSILON);
    }

    @Test
    public void testSqrt_NegativeRealWithImaginary() {
        // sqrt(-3 + 4i)
        // abs = 5. t = sqrt((3+5)/2) = 2.
        // real < 0: real = |4| / (2*2) = 1, imag = indicator(4)*2 = 2
        // Result: 1 + 2i. (Check: (1+2i)^2 = 1 - 4 + 4i = -3 + 4i)
        Complex c = new Complex(-3.0, 4.0);
        Complex result = c.sqrt();
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(2.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testSqrt_NegativeRealWithNegativeImaginary() {
        // sqrt(-3 - 4i)
        // abs = 5. t = 2.
        // real < 0: real = |-4| / (2*2) = 1, imag = indicator(-4)*2 = -2
        // Result: 1 - 2i. (Check: (1-2i)^2 = 1 - 4 - 4i = -3 - 4i)
        Complex c = new Complex(-3.0, -4.0);
        Complex result = c.sqrt();
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(-2.0, result.getImaginary(), EPSILON);
    }
}
